#!/usr/bin/env python3
import sys, os, re, glob, html as htmlmod
from html.parser import HTMLParser
from urllib.parse import urljoin, quote, urlsplit, urlunsplit

HELP_TEXT = r'''
# html2markdown - convert html to markdown [version dev]

Convert HTML to Markdown. Even works with entire websites!

## Basics

By default the "Commonmark" Plugin will be enabled. You can customize the options,
for example changing the appearance of bold with --opt-strong-delimiter="__"

Other Plugins can also be enabled. For example "GitHub Flavored Markdown" (GFM)
extends Commonmark with more features.

## Relative / Absolute Links

Use --domain="https://example.com" to convert *relative* links to *absolute* links.
The same also works for images.

## Escaping

Some characters have a special meaning in markdown. The library escapes these — if necessary.
See the documentation for more info.

## Security

Once you convert this markdown *back* to HTML you need to be careful of malicious content. 
Use a HTML sanitizer before displaying the HTML in the browser!


## Examples

    echo "<strong>important</strong>" | html2markdown

    curl --no-progress-meter http://example.com | html2markdown


    html2markdown --input file.html --output file.md

    html2markdown --input "src/*.html" --output "dist/"


## Flags

    -v, --version
        show the version of html2markdown and exit

    --help

    --input PATH
        Input file, directory, or glob pattern (instead of stdin)

    --output PATH
        Output file or directory (instead of stdout)

    --output-overwrite
        Replace existing files

    If --input is a directory or glob pattern, --output must be a directory.



    --domain
        The url of the web page, used to convert relative links to absolute links.

    --exclude-selector
        css query selector to exclude parts of the input

    --include-selector
        css query selector to only include parts of the input

    --opt-strong-delimiter
        Make bold text. Should <strong> be indicated by two asterisks or two underscores?
        "**" or "__" (default: "**")

    --opt-table-cell-padding-behavior
        [for --plugin-table] whether cells in the tables should include extra padding for visual continuity: "aligned", "minimal", or "none"

    --opt-table-header-promotion
        [for --plugin-table] first row should be treated as a header

    --opt-table-newline-behavior
        [for --plugin-table] how tables containing newlines should be handled: "skip" or "preserve"

    --opt-table-presentation-tables
        [for --plugin-table] whether tables with role="presentation" should be converted

    --opt-table-skip-empty-rows
        [for --plugin-table] omit empty rows from the output

    --opt-table-span-cell-behavior
        [for --plugin-table] how colspan/rowspan should be rendered: "empty" or "mirror"

    --plugin-strikethrough
        enable the plugin ~~strikethrough~~

    --plugin-table
        enable the plugin table



For more information visit the documentation:
https://github.com/Johanneskaufmann/html-to-markdown
'''
VERSION_TEXT = '''html2markdown

GitVersion:  dev
GitCommit:   none
BuildDate:   unknown
'''
USAGE_STDIN = '''
error: the html input should be piped into the cli

Here is how you can use the CLI:

    echo "<strong>important</strong>" | html2markdown
'''
USAGE_UNKNOWN = '''
error: {msg}

Here is how you can use the CLI:

    echo "<strong>important</strong>" | html2markdown
'''
USAGE_GLOB = '''
error: {msg}

Here is how you can use a glob to match multiple files:

    html2markdown --input "src/*.html" --output "dist/"
'''

class Node:
    __slots__ = ('tag','attrs','children','text','parent')
    def __init__(self, tag=None, attrs=None, text=None):
        self.tag = tag
        self.attrs = dict(attrs or [])
        self.children = []
        self.text = text
        self.parent = None
    def append(self, n):
        n.parent = self
        self.children.append(n)

VOID_TAGS = set('area base br col embed hr img input link meta param source track wbr'.split())
SKIP_CONTENT_TAGS = {'script','style','head','title','iframe','noscript'}

class Parser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=False)
        self.root = Node('document')
        self.stack = [self.root]
        self.skip_depth = 0
    def handle_starttag(self, tag, attrs):
        tag = tag.lower()
        if self.skip_depth:
            if tag in SKIP_CONTENT_TAGS:
                self.skip_depth += 1
            return
        if tag in SKIP_CONTENT_TAGS:
            self.skip_depth = 1
            return
        n = Node(tag, attrs)
        self.stack[-1].append(n)
        if tag not in VOID_TAGS:
            self.stack.append(n)
    def handle_startendtag(self, tag, attrs):
        tag = tag.lower()
        if self.skip_depth:
            return
        if tag in SKIP_CONTENT_TAGS:
            return
        n = Node(tag, attrs)
        self.stack[-1].append(n)
    def handle_endtag(self, tag):
        tag = tag.lower()
        if self.skip_depth:
            if tag in SKIP_CONTENT_TAGS:
                self.skip_depth -= 1
            return
        for i in range(len(self.stack)-1, 0, -1):
            if self.stack[i].tag == tag:
                del self.stack[i:]
                return
    def _add_text(self, s):
        if self.skip_depth:
            return
        if s:
            self.stack[-1].append(Node(text=s))
    def handle_data(self, data):
        self._add_text(data)
    def handle_entityref(self, name):
        self._add_text(htmlmod.unescape('&'+name+';'))
    def handle_charref(self, name):
        self._add_text(htmlmod.unescape('&#'+name+';'))
    def handle_comment(self, data):
        pass
    def handle_decl(self, decl):
        pass

class Options:
    def __init__(self):
        self.strong_delim = '**'
        self.domain = ''
        self.plugin_strike = False
        self.plugin_table = False
        self.include_selector = None
        self.exclude_selector = None
        self.table_padding = 'aligned'
        self.table_header_promotion = False
        self.table_newline = 'skip'
        self.table_presentation = False
        self.table_skip_empty = False
        self.table_span = 'empty'

BLOCK_TAGS = {
    'address','article','aside','blockquote','body','center','dd','details','dialog','dir','div','dl','dt',
    'fieldset','figcaption','figure','footer','form','hgroup','html','header','hr','li','main','menu','nav','ol',
    'p','pre','section','summary','table','tbody','td','tfoot','th','thead','tr','ul',
    'h1','h2','h3','h4','h5','h6'
}

# tags whose children are just concatenated inline if not otherwise handled
INLINE_TAGS = set('a abbr acronym b bdi bdo big br button cite code data del dfn em font i img input ins kbd label mark q rp rt ruby s samp small span strike strong sub sup time tt u var wbr'.split())

def parse_html(s):
    p = Parser()
    try:
        p.feed(s)
        p.close()
    except Exception:
        pass
    return p.root

def normalize_ws(s):
    # Treat ordinary HTML whitespace as collapsible; NBSP survives.
    return re.sub(r'[\t\n\r\f ]+', ' ', s)

def trim_inline(s):
    return re.sub(r'^[\t\n\r\f ]+|[\t\n\r\f ]+$', '', s)

def collapse_inline(s):
    s = normalize_ws(s)
    # remove spaces around line breaks generated by <br>
    s = re.sub(r' *\n *', '\n', s)
    return s.strip(' ')

def escape_url(u, domain=''):
    if u is None:
        u = ''
    u = htmlmod.unescape(u)
    if domain and u and not re.match(r'^[a-zA-Z][a-zA-Z0-9+.-]*:', u):
        u = urljoin(domain, u)
    # encode spaces and a few unsafe characters but leave common URL syntax alone
    return quote(u, safe=':/?#[]@!$&\'()*+,;=%')

def escape_title(t):
    return (t or '').replace('"','\\"')

def escape_text(s, in_table=False):
    if not s:
        return ''
    s = s.replace('\\', '\\\\')
    s = s.replace('<', '&lt;').replace('>', '&gt;')
    # backticks always escaped in prose
    s = s.replace('`', '\\`')
    # Escape link-open brackets when they can form links/images; this is a pragmatic approximation
    s = re.sub(r'!\[', r'!\\[', s)
    s = re.sub(r'\[([^\]]*)\]', lambda m: r'\[' + m.group(1) + ']', s)
    if in_table:
        s = s.replace('|', '\\|')
    # Escape emphasis markers where they can start emphasis or thematic breaks.
    def esc_stars(m):
        run = m.group(0)
        # match observed smart-ish behavior: leave the last star of a run unescaped except one-char run
        if len(run) == 1:
            return '\\*'
        return ''.join('\\*' for _ in run[:-1]) + '*'
    def esc_unders(m):
        run = m.group(0)
        if len(run) == 1:
            return '_'
        return ''.join('\\_' for _ in run[:-1]) + '_'
    # runs attached to non-space or at beginning are dangerous
    s = re.sub(r'(?<!\s)\*+|(?<=\s)\*+(?=\S)|^\*+', esc_stars, s)
    s = re.sub(r'(?<!\s)_+|(?<=\s)_+(?=\S)|^_+', esc_unders, s)
    # line-start constructs
    lines = s.split('\n')
    out=[]
    for line in lines:
        line = re.sub(r'^(#{1,6})(\s|$)', lambda m: '\\' + m.group(1) + m.group(2), line)
        line = re.sub(r'^([+-])(\s|$)', lambda m: '\\' + m.group(1) + m.group(2), line)
        line = re.sub(r'^-(\s|$)', lambda m: '\\-' + m.group(1), line)
        line = re.sub(r'^(-{3,}|\*{3,}|_{3,})$', lambda m: '\\' + m.group(1), line)
        line = re.sub(r'^(\d+)([.)])(\s|$)', lambda m: m.group(1) + '\\' + m.group(2) + m.group(3), line)
        line = re.sub(r'^(=+)$', lambda m: '\\' + m.group(1) if len(m.group(1))<=2 else m.group(1), line)
        out.append(line)
    return '\n'.join(out)

def text_content(node):
    if node.text is not None:
        return node.text
    return ''.join(text_content(c) for c in node.children)

def max_backtick_run(s):
    runs = re.findall(r'`+', s)
    return max([len(r) for r in runs] or [0])

def inline_code(s):
    s = htmlmod.unescape(s)
    s = s.strip(' \t\r\n')
    n = max(1, max_backtick_run(s)+1)
    ticks = '`'*n
    return ticks + s + ticks

def block_code(content, lang=''):
    content = htmlmod.unescape(content)
    # the converter drops one terminal newline before closing fence
    if content.endswith('\n'):
        content = content[:-1]
    n = max(3, max_backtick_run(content)+1)
    ticks = '`'*n
    first = ticks + (lang or '')
    return first + '\n' + content + '\n' + ticks

def code_language(pre_node):
    # language on pre or child code class: language-X or lang-X
    candidates = []
    if pre_node:
        candidates.append(pre_node)
        for c in pre_node.children:
            if c.tag == 'code':
                candidates.append(c)
    for n in candidates:
        cls = n.attrs.get('class','') if n.attrs else ''
        for part in re.split(r'\s+', cls):
            if part.startswith('language-') and len(part)>9:
                return part[9:]
            if part.startswith('lang-') and len(part)>5:
                return part[5:]
    return ''

class Converter:
    def __init__(self, opt):
        self.opt = opt

    def convert(self, root):
        if self.opt.exclude_selector:
            self.apply_exclude(root, self.opt.exclude_selector)
        roots = [root]
        if self.opt.include_selector:
            roots = self.select_all(root, self.opt.include_selector)
        parts=[]
        for r in roots:
            md = self.render_block(r)
            if md.strip() or md != '':
                parts.append(md.strip('\n'))
        out = '\n\n'.join([p for p in parts if p!=''])
        return out + '\n'

    def render_children_blocks(self, node):
        parts=[]
        inline_buf=[]
        def flush_inline():
            nonlocal inline_buf
            if inline_buf:
                s = collapse_inline(''.join(inline_buf))
                if s:
                    parts.append(s)
                inline_buf=[]
        for c in node.children:
            if c.text is not None:
                inline_buf.append(self.render_inline(c))
            elif self.is_block_node(c):
                flush_inline()
                md = self.render_block(c)
                if md.strip() or c.tag in ('pre','hr'):
                    parts.append(md.strip('\n'))
            else:
                inline_buf.append(self.render_inline(c))
        flush_inline()
        return '\n\n'.join(parts)

    def is_block_node(self, node):
        if node.text is not None: return False
        if node.tag in ('br','img','a','strong','b','em','i','code','span','del','s','strike','input'): return False
        return node.tag in BLOCK_TAGS or any((ch.text is None and self.is_block_node(ch)) for ch in node.children)

    def render_block(self, node):
        if node.text is not None:
            return collapse_inline(self.render_inline(node))
        tag = node.tag or ''
        if tag == 'document' or tag in ('html','body'):
            return self.render_children_blocks(node)
        if tag in ('h1','h2','h3','h4','h5','h6'):
            level = int(tag[1])
            content = collapse_inline(self.render_inlines(node))
            return '#' * level + ' ' + content if content else '#' * level
        if tag == 'p':
            return collapse_inline(self.render_inlines(node))
        if tag == 'br':
            return '  \n'
        if tag == 'hr':
            return '* * *'
        if tag == 'blockquote':
            inner = self.render_children_blocks(node).strip('\n')
            if not inner:
                return '>'
            return '\n'.join(('> ' + line if line else '> ') for line in inner.split('\n'))
        if tag in ('ul','ol'):
            return self.render_list(node, ordered=(tag=='ol'))
        if tag == 'li':
            return self.render_li_content(node)
        if tag == 'pre':
            return block_code(text_content(node), code_language(node))
        if tag == 'table':
            if self.opt.plugin_table and (self.opt.table_presentation or node.attrs.get('role','').lower() != 'presentation'):
                maybe = self.render_table(node)
                if maybe is not None:
                    return maybe
            return self.render_children_blocks_no_table_structure(node)
        if tag in ('thead','tbody','tfoot','tr'):
            return self.render_children_blocks(node)
        if tag in ('td','th'):
            return collapse_inline(self.render_inlines(node))
        # default block-ish container
        return self.render_children_blocks(node)

    def render_children_blocks_no_table_structure(self, node):
        # presentation/fallback table: concatenate cells in row order, preserving block children roughly.
        if node.text is not None:
            return collapse_inline(self.render_inline(node))
        parts=[]
        for c in node.children:
            if c.text is not None:
                txt=collapse_inline(self.render_inline(c))
                if txt: parts.append(txt)
            elif c.tag in ('thead','tbody','tfoot','tr','td','th'):
                md=self.render_children_blocks_no_table_structure(c)
                if md: parts.append(md)
            elif c.tag == 'caption':
                md=self.render_block(c)
                if md: parts.append(md)
            else:
                md=self.render_block(c) if self.is_block_node(c) else collapse_inline(self.render_inline(c))
                if md: parts.append(md)
        # cells in a simple row have no separator in observed fallback
        return ''.join(parts) if node.tag in ('tr','td','th','thead','tbody','tfoot','table') else '\n\n'.join(parts)

    def render_inlines(self, node, in_table=False):
        return ''.join(self.render_inline(c, in_table=in_table) for c in node.children)

    def render_inline(self, node, in_table=False):
        if node.text is not None:
            return escape_text(normalize_ws(node.text), in_table=in_table)
        tag = node.tag
        if tag == 'br':
            return '  \n'
        if tag in ('strong','b'):
            inner = collapse_inline(self.render_inlines(node, in_table=in_table))
            return self.opt.strong_delim + inner + self.opt.strong_delim if inner else ''
        if tag in ('em','i'):
            inner = collapse_inline(self.render_inlines(node, in_table=in_table))
            return '*' + inner + '*' if inner else ''
        if tag in ('del','s','strike'):
            inner = collapse_inline(self.render_inlines(node, in_table=in_table))
            if self.opt.plugin_strike and inner:
                return '~~' + inner + '~~'
            return inner
        if tag == 'code':
            return inline_code(text_content(node))
        if tag == 'a':
            inner = collapse_inline(self.render_inlines(node, in_table=in_table))
            href = escape_url(node.attrs.get('href',''), self.opt.domain)
            title = node.attrs.get('title')
            if title is not None:
                return '[' + inner + '](' + href + ' "' + escape_title(htmlmod.unescape(title)) + '")'
            return '[' + inner + '](' + href + ')'
        if tag == 'img':
            alt = htmlmod.unescape(node.attrs.get('alt',''))
            alt = alt.replace('\\','\\\\').replace('[','\\[').replace(']','\\]')
            src = escape_url(node.attrs.get('src',''), self.opt.domain)
            title = node.attrs.get('title')
            if title is not None:
                return '![' + alt + '](' + src + ' "' + escape_title(htmlmod.unescape(title)) + '")'
            return '![' + alt + '](' + src + ')'
        if tag == 'input':
            return ''
        if self.is_block_node(node):
            return self.render_block(node)
        return self.render_inlines(node, in_table=in_table)

    def render_list(self, node, ordered=False):
        items = [c for c in node.children if c.text is None and c.tag == 'li']
        start = 1
        if ordered:
            try: start = int(node.attrs.get('start','1'))
            except Exception: start = 1
        lines=[]
        for idx, li in enumerate(items):
            marker = (str(start+idx)+'. ') if ordered else '- '
            indent = ' ' * len(marker)
            content = self.render_li_content(li).strip('\n')
            if not content:
                lines.append(marker.rstrip())
                continue
            clines = content.split('\n')
            lines.append(marker + clines[0])
            for l in clines[1:]:
                lines.append(indent + l)
        return '\n'.join(lines)

    def render_li_content(self, li):
        parts=[]; inline_buf=[]
        def flush_inline():
            nonlocal inline_buf
            if inline_buf:
                s=collapse_inline(''.join(inline_buf))
                if s: parts.append(s)
                inline_buf=[]
        for c in li.children:
            if c.text is not None:
                inline_buf.append(self.render_inline(c))
            elif c.tag in ('ul','ol'):
                flush_inline()
                md=self.render_list(c, ordered=(c.tag=='ol')).strip('\n')
                if md: parts.append(md)
            elif self.is_block_node(c) and c.tag not in ('p',):
                flush_inline()
                md=self.render_block(c).strip('\n')
                if md: parts.append(md)
            elif c.tag == 'p':
                flush_inline()
                md=collapse_inline(self.render_inlines(c))
                if md: parts.append(md)
            else:
                inline_buf.append(self.render_inline(c))
        flush_inline()
        return '\n\n'.join(parts)

    # Table handling
    def table_rows(self, table):
        rows=[]; captions=[]
        def walk(n):
            if n.text is not None: return
            if n.tag == 'caption':
                cap = self.render_block(n).strip('\n')
                if cap: captions.append(cap)
                return
            if n.tag == 'tr':
                rows.append(n); return
            for ch in n.children: walk(ch)
        walk(table)
        return rows, captions

    def render_table(self, table):
        rows_nodes, captions = self.table_rows(table)
        if not rows_nodes:
            return self.render_children_blocks_no_table_structure(table)
        grid=[]; header_flags=[]; occupied={}
        maxcols=0
        for r, tr in enumerate(rows_nodes):
            row=[]; cidx=0; flags=[]
            # fill occupied from prior row as needed during placement
            cells=[c for c in tr.children if c.text is None and c.tag in ('td','th')]
            for cell in cells:
                while (r,cidx) in occupied:
                    row.append(occupied[(r,cidx)] if self.opt.table_span=='mirror' else '')
                    flags.append(False); cidx += 1
                txt = collapse_inline(self.render_inlines(cell, in_table=True))
                # skip tables with newlines unless preserve
                if '\n' in txt and self.opt.table_newline != 'preserve':
                    return self.render_children_blocks_no_table_structure(table)
                if self.opt.table_newline == 'preserve':
                    txt = txt.replace('  \n','<br />').replace('\n','<br />')
                try: colspan=max(1,int(cell.attrs.get('colspan','1')))
                except: colspan=1
                try: rowspan=max(1,int(cell.attrs.get('rowspan','1')))
                except: rowspan=1
                for cc in range(colspan):
                    val = txt if (cc==0 or self.opt.table_span=='mirror') else ''
                    row.append(val); flags.append(cell.tag=='th');
                    for rr in range(1,rowspan):
                        occupied[(r+rr,cidx)] = txt if self.opt.table_span=='mirror' else ''
                    cidx += 1
            while (r,cidx) in occupied:
                row.append(occupied[(r,cidx)] if self.opt.table_span=='mirror' else '')
                flags.append(False); cidx += 1
            maxcols=max(maxcols,len(row)); grid.append(row); header_flags.append(flags)
        for row,flags in zip(grid, header_flags):
            while len(row)<maxcols: row.append('')
            while len(flags)<maxcols: flags.append(False)
        if self.opt.table_skip_empty:
            grid2=[]; flags2=[]
            for row,fl in zip(grid, header_flags):
                if any(cell.strip() for cell in row):
                    grid2.append(row); flags2.append(fl)
            grid, header_flags = grid2, flags2
        if not grid:
            return ''
        header_idx = None
        for i, fl in enumerate(header_flags):
            if any(fl): header_idx=i; break
        if self.opt.table_header_promotion:
            header_idx = 0
        if header_idx is None:
            header = ['']*maxcols
            body = grid
        else:
            header = grid[header_idx]
            body = grid[:header_idx] + grid[header_idx+1:]
        lines = self.format_table(header, body)
        md='\n'.join(lines)
        if captions:
            md += '\n\n' + '\n\n'.join(captions)
        return md

    def format_table(self, header, body):
        rows=[header]+body
        n=len(header)
        if self.opt.table_padding == 'none':
            def rowline(row): return '|' + '|'.join(row) + '|'
            return [rowline(header), '|' + '|'.join(['---']*n) + '|'] + [rowline(r) for r in body]
        if self.opt.table_padding == 'minimal':
            def rowline(row): return '| ' + ' | '.join(row) + ' |'
            return [rowline(header), '|' + '|'.join(['---']*n) + '|'] + [rowline(r) for r in body]
        # aligned: widths from all cells and separator minimum 3
        widths=[]
        for c in range(n):
            maxlen=max([len(row[c]) if c < len(row) else 0 for row in rows] + [0])
            widths.append(max(3,maxlen))
        def rowline(row):
            cells=[]
            for c in range(n):
                val = row[c] if c < len(row) else ''
                cells.append(' ' + val.ljust(widths[c]) + ' ')
            return '|' + '|'.join(cells) + '|'
        sep='|' + '|'.join('-'*w for w in widths) + '|'
        return [rowline(header), sep] + [rowline(r) for r in body]

    # Simple selector support: tag, #id, .class, tag.class, tag#id and comma-separated.
    def matches(self, node, sel):
        if node.text is not None: return False
        sel=sel.strip()
        if not sel: return False
        # handle descendant selector by checking only last component for practical compatibility
        if ' ' in sel:
            parts=[p for p in sel.split() if p]
            return self.matches(node, parts[-1])
        tag=None; idv=None; classes=[]
        m=re.match(r'^([a-zA-Z][\w-]*)?', sel)
        pos=0
        if m and m.group(0):
            tag=m.group(0).lower(); pos=len(m.group(0))
        while pos < len(sel):
            if sel[pos]=='#':
                pos+=1; m=re.match(r'[\w-]+', sel[pos:]);
                if not m: return False
                idv=m.group(0); pos+=len(idv)
            elif sel[pos]=='.':
                pos+=1; m=re.match(r'[\w-]+', sel[pos:]);
                if not m: return False
                classes.append(m.group(0)); pos+=len(classes[-1])
            else:
                return False
        if tag and node.tag != tag: return False
        if idv and node.attrs.get('id') != idv: return False
        cls=set(re.split(r'\s+', node.attrs.get('class','').strip())) if node.attrs.get('class') else set()
        return all(c in cls for c in classes)

    def select_all(self, root, selector):
        sels=[s.strip() for s in selector.split(',') if s.strip()]
        out=[]
        def walk(n):
            if n.text is None:
                if any(self.matches(n,s) for s in sels): out.append(n)
                for ch in n.children: walk(ch)
        walk(root)
        return out

    def apply_exclude(self, root, selector):
        sels=[s.strip() for s in selector.split(',') if s.strip()]
        def filt(n):
            if n.text is not None: return True
            new=[]
            for ch in n.children:
                if ch.text is None and any(self.matches(ch,s) for s in sels):
                    continue
                if filt(ch): new.append(ch)
            n.children=new
            return True
        filt(root)

def parse_args(argv):
    opt=Options(); input_path=None; output_path=None; overwrite=False
    i=0
    needs_value={'--input':'input','-input':'input','--output':'output','-output':'output','--domain':'domain','-domain':'domain',
                 '--include-selector':'include','-include-selector':'include','--exclude-selector':'exclude','-exclude-selector':'exclude',
                 '--opt-strong-delimiter':'strong','-opt-strong-delimiter':'strong',
                 '--opt-table-cell-padding-behavior':'tpad','-opt-table-cell-padding-behavior':'tpad',
                 '--opt-table-newline-behavior':'tnl','-opt-table-newline-behavior':'tnl',
                 '--opt-table-span-cell-behavior':'tspan','-opt-table-span-cell-behavior':'tspan'}
    bools={'--output-overwrite':'overwrite','-output-overwrite':'overwrite','--plugin-strikethrough':'strike','-plugin-strikethrough':'strike',
           '--plugin-table':'table','-plugin-table':'table','--opt-table-header-promotion':'thp','-opt-table-header-promotion':'thp',
           '--opt-table-presentation-tables':'tpt','-opt-table-presentation-tables':'tpt','--opt-table-skip-empty-rows':'tser','-opt-table-skip-empty-rows':'tser'}
    while i < len(argv):
        a=argv[i]
        if a in ('--help','-h'):
            print(HELP_TEXT, end='')
            sys.exit(0)
        if a in ('--version','-version','-v'):
            print(VERSION_TEXT, end='')
            sys.exit(0)
        val=None; key=a
        if '=' in a and a.startswith('-'):
            key,val=a.split('=',1)
        if key in needs_value:
            if val is None:
                if i+1 >= len(argv):
                    sys.stderr.write(f"\nerror: flag needs an argument: {key.replace('--','-')}\n")
                    sys.exit(1)
                i+=1; val=argv[i]
            kind=needs_value[key]
            if kind=='input': input_path=val
            elif kind=='output': output_path=val
            elif kind=='domain': opt.domain=val
            elif kind=='include': opt.include_selector=val
            elif kind=='exclude': opt.exclude_selector=val
            elif kind=='strong':
                if val not in ('**','__'):
                    sys.stderr.write(f"\nerror: invalid value for --opt-strong-delimiter=\"{val}\" must be exactly 2 characters of \"**\" or \"__\"\n")
                    sys.exit(1)
                opt.strong_delim=val
            elif kind=='tpad':
                if val not in ('aligned','minimal','none'):
                    sys.stderr.write(f"\nerror: invalid value for --opt-table-cell-padding-behavior=\"{val}\" must be one of \"aligned\", \"minimal\", or \"none\"\n")
                    sys.exit(1)
                opt.table_padding=val
            elif kind=='tnl':
                if val not in ('skip','preserve'):
                    sys.stderr.write(f"\nerror: invalid value for --opt-table-newline-behavior=\"{val}\" must be \"skip\" or \"preserve\"\n")
                    sys.exit(1)
                opt.table_newline=val
            elif kind=='tspan':
                if val not in ('empty','mirror'):
                    sys.stderr.write(f"\nerror: invalid value for --opt-table-span-cell-behavior=\"{val}\" must be \"empty\" or \"mirror\"\n")
                    sys.exit(1)
                opt.table_span=val
        elif key in bools and val is None:
            kind=bools[key]
            if kind=='overwrite': overwrite=True
            elif kind=='strike': opt.plugin_strike=True
            elif kind=='table': opt.plugin_table=True
            elif kind=='thp': opt.table_header_promotion=True
            elif kind=='tpt': opt.table_presentation=True
            elif kind=='tser': opt.table_skip_empty=True
        else:
            if a.startswith('-'):
                sys.stderr.write(f"\nerror: unknown flag: {a}\n")
            else:
                sys.stderr.write(USAGE_UNKNOWN.format(msg='unknown arguments: '+a))
            sys.exit(1)
        i+=1
    return opt,input_path,output_path,overwrite

def convert_html(s, opt):
    root=parse_html(s)
    return Converter(opt).convert(root)

def is_glob_pattern(p):
    return any(ch in p for ch in '*?[')

def input_files(path):
    if os.path.isdir(path):
        sys.stderr.write(USAGE_GLOB.format(msg=f'input path "{path}" is a directory, not a file'))
        sys.exit(1)
    if is_glob_pattern(path):
        files=glob.glob(path, recursive=True)
        files=[f for f in files if os.path.isfile(f)]
        files.sort()
        if not files:
            sys.stderr.write(USAGE_GLOB.format(msg=f'no files found matching pattern "{path}"'))
            sys.exit(1)
        return files, True
    if not os.path.isfile(path):
        # original phrases missing file as no files found matching pattern
        files=glob.glob(path, recursive=True)
        files=[f for f in files if os.path.isfile(f)]
        if not files:
            sys.stderr.write(USAGE_GLOB.format(msg=f'no files found matching pattern "{path}"'))
            sys.exit(1)
        return sorted(files), len(files)>1
    return [path], False

def output_file_for(inp, outpath, multi):
    if outpath is None:
        return None
    if outpath.endswith('/'):
        base=os.path.basename(inp)
        stem=os.path.splitext(base)[0]
        return os.path.join(outpath, stem+'.md')
    if multi:
        bn=os.path.basename(outpath)
        sys.stderr.write(f'\nerror: path "{bn}" exists and is a directory, did you mean "{bn}/"?\n\nThe --output must end with "/" to indicate a directory\n')
        sys.exit(1)
    return outpath

def main(argv):
    opt,input_path,output_path,overwrite=parse_args(argv)
    if input_path is None:
        if sys.stdin.isatty():
            sys.stderr.write(USAGE_STDIN)
            return 1
        data=sys.stdin.read()
        out=convert_html(data,opt)
        if output_path:
            target=output_path
            if os.path.exists(target) and not overwrite:
                sys.stderr.write(f'\nerror: output path "{target}" already exists. Use --output-overwrite to replace existing files\n')
                return 1
            parent=os.path.dirname(target)
            if parent: os.makedirs(parent, exist_ok=True)
            with open(target,'w',encoding='utf-8') as f: f.write(out.rstrip('\n'))
        else:
            sys.stdout.write(out)
        return 0
    files,multi=input_files(input_path)
    multi = multi or len(files)>1
    if multi and output_path is not None and not output_path.endswith('/'):
        bn=os.path.basename(output_path.rstrip('/'))
        sys.stderr.write(f'\nerror: path "{bn}" exists and is a directory, did you mean "{bn}/"?\n\nThe --output must end with "/" to indicate a directory\n')
        return 1
    for fpath in files:
        with open(fpath,'r',encoding='utf-8',errors='replace') as f: data=f.read()
        out=convert_html(data,opt)
        if output_path is None:
            sys.stdout.write(out)
        else:
            target=output_file_for(fpath, output_path, multi)
            if os.path.exists(target) and not overwrite:
                sys.stderr.write(f'\nerror: output path "{target}" already exists. Use --output-overwrite to replace existing files\n')
                return 1
            parent=os.path.dirname(target)
            if parent: os.makedirs(parent, exist_ok=True)
            with open(target,'w',encoding='utf-8') as outf: outf.write(out.rstrip('\n'))
    return 0

if __name__ == '__main__':
    sys.exit(main(sys.argv[1:]))
